import{_ as i,o as t,c as r,a5 as a}from"./chunks/framework.DrDMl0tG.js";const o="/assets/robotiq_gripper_mimic.COj9QCxz.png",u=JSON.parse('{"title":"Server Example: Robotiq Gripper Mimic","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/robotiq_gripper_mimic.md","filePath":"sections/examples/server/robotiq_gripper_mimic.md"}'),s={name:"sections/examples/server/robotiq_gripper_mimic.md"};function n(c,e,l,d,p,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="server-example-robotiq-gripper-mimic" tabindex="-1">Server Example: Robotiq Gripper Mimic <a class="header-anchor" href="#server-example-robotiq-gripper-mimic" aria-label="Permalink to &quot;Server Example: Robotiq Gripper Mimic&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A fixed-base, six-axis Kinova arm carries a wrist-mounted Robotiq 2F-85 through predefined joint positions to pick up a cube at the blue marker and release it at the green marker. The arm returns to its starting pose, resets the world, and repeats the 21.5-second cycle. All motion during the task comes from joint PD control and physical contacts.</p><p>The gripper is driven by its left knuckle. Its five other finger joints remain passive and follow through URDF <code>&lt;mimic&gt;</code> constraints (see <a href="./../../articulated_system/MimicJoints.html">Mimic Joints</a>).</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><img src="'+o+'" alt="Kinova arm carrying a cube with its wrist-mounted Robotiq 2F-85" style="width:80%;"><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>robotiq_gripper_mimic</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable and connect <code>rayrai_tcp_viewer</code> to port 8080:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/robotiq_gripper_mimic</span></span></code></pre></div><p>On Windows, run <code>build-examples/bin/robotiq_gripper_mimic.exe</code> instead. The example discovers its resource folder relative to the executable or working directory. Normal RaiSim license discovery applies; use <code>--activation-key /path/to/activation.raisim</code> for an explicit license. <code>--port N</code> changes the server port. The example repeats until interrupted; <code>--cycles N</code> stops it after N cycles.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads <code>rsc/robotiq_2f85/kinova_robotiq.urdf</code>. The combined model reuses the bundled BSD-licensed Kinova arm and Robotiq descriptions and meshes. A fixed flange replaces the Kinova three-finger hand and the vertical <code>lift</code> joint of the standalone gripper model (<code>rsc/robotiq_2f85/robotiq_2f85_mimic.urdf</code>).</li><li>Only the six arm joints and <code>robotiq_85_left_knuckle_joint</code> have PD gains. The five mimic followers have zero gains; the fingertips counter-rotate so the pads remain parallel.</li><li>The cube is 40 mm on each side and weighs 100 g. It moves 360 mm between the table markers and rises about 200 mm during transfer.</li><li>Four predefined arm configurations specify pickup, pickup hover, destination hover, and placement. A quintic interpolation supplies continuous position and velocity targets with zero velocity and acceleration at phase boundaries. Changing the model or marker positions requires updating these configurations.</li><li>The closing target goes past the cube width, so the knuckle PD squeezes the cube. Pad friction supports the cube throughout lifting and transfer.</li><li>After release, retraction, and return, the example restores a checkpoint of the settled initial world, including robot/cube state and solver history. The cube is repositioned only by this explicit reset at the cycle boundary.</li><li>Controller updates run inside the RaisimServer world mutex and follow simulation time, so viewer pause and queued single-step pause the sequence.</li></ul>',14)])])}const b=i(s,[["render",n]]);export{u as __pageData,b as default};
